16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.TelephoneFormatter;
20	
21	import jakarta.persistence.*;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.time.Period;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "postcode")
57	    private String postcode;
58	
59	    @Column(name = "registration_date", columnDefinition = "DATE")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "birth_date", columnDefinition = "DATE")
63	    private LocalDate birthDate;
64	
65	    @Column(name = "customer_code")
66	    private String customerCode;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "possible_duplicate")
75	    private Boolean possibleDuplicate;
76	
77	    @Column(name = "possible_duplicate_of")
78	    private Integer possibleDuplicateOf;
79	
80	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
81	    private Set<Pet> pets;
82	
83	    public String getAddress() {
84	        return this.address;
85	    }
86	
87	    public void setAddress(String address) {
88	        this.address = address;
89	    }
90	
91	    public String getCity() {
92	        return this.city;
93	    }
94	
95	    public void setCity(String city) {
96	        this.city = city;
97	    }
98	
99	    public String getTelephone() {
100	        return this.telephone;
101	    }
102	
103	    public void setTelephone(String telephone) {
104	        this.telephone = telephone;
105	    }
106	
107	    /**
108	     * The stored E.164 {@code telephone} formatted for humans (e.g. {@code '+61 412 345 678'} for the
109	     * stored {@code '+61412345678'}); the raw {@code telephone} stays in E.164 form. Derived from the
110	     * owner's own {@code telephone}; see {@link TelephoneFormatter#toDisplay(String)}.
111	     */
112	    @Transient
113	    public String getTelephoneDisplay() {
114	        return TelephoneFormatter.toDisplay(this.telephone);
115	    }
116	
117	    public String getEmail() {
118	        return this.email;
119	    }
120	
121	    public void setEmail(String email) {
122	        this.email = email;
123	    }
124	
125	    public String getPostcode() {
126	        return this.postcode;
127	    }
128	
129	    public void setPostcode(String postcode) {
130	        this.postcode = postcode;
131	    }
132	
133	    public LocalDate getRegistrationDate() {
134	        return this.registrationDate;
135	    }
136	
137	    public void setRegistrationDate(LocalDate registrationDate) {
138	        this.registrationDate = registrationDate;
139	    }
140	
141	    public LocalDate getBirthDate() {
142	        return this.birthDate;
143	    }
144	
145	    public void setBirthDate(LocalDate birthDate) {
146	        this.birthDate = birthDate;
147	    }
148	
149	    public String getCustomerCode() {
150	        return this.customerCode;
151	    }
152	
153	    public void setCustomerCode(String customerCode) {
154	        this.customerCode = customerCode;
155	    }
156	
157	    public String getHouseholdId() {
158	        return this.householdId;
159	    }
160	
161	    public void setHouseholdId(String householdId) {
162	        this.householdId = householdId;
163	    }
164	
165	    public Integer getNamesakeCount() {
166	        return this.namesakeCount;
167	    }
168	
169	    public void setNamesakeCount(Integer namesakeCount) {
170	        this.namesakeCount = namesakeCount;
171	    }
172	
173	    /**
174	     * Whether this owner was flagged a possible (soft) duplicate at creation time: it was not a
175	     * hard duplicate, but shared an existing owner's last name and postcode while carrying a
176	     * different telephone. {@code false} (or {@code null} for owners created before the check) when
177	     * no such match was found.
178	     */
179	    public Boolean getPossibleDuplicate() {
180	        return this.possibleDuplicate;
181	    }
182	
183	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
184	        this.possibleDuplicate = possibleDuplicate;
185	    }
186	
187	    /**
188	     * The id of the existing owner this one was flagged a possible duplicate of, or {@code null}
189	     * when {@code possibleDuplicate} is not set.
190	     */
191	    public Integer getPossibleDuplicateOf() {
192	        return this.possibleDuplicateOf;
193	    }
194	
195	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
196	        this.possibleDuplicateOf = possibleDuplicateOf;
197	    }
198	
199	    /**
200	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
201	     */
202	    @Transient
203	    public String getDisplayName() {
204	        return this.getLastName() + ", " + this.getFirstName();
205	    }
206	
207	    /**
208	     * The owner's initials: the upper-cased first letters of the first and last name,
209	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
210	     */
211	    @Transient
212	    public String getInitials() {
213	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
214	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
215	    }
216	
217	    /**
218	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
219	     * the last two digits of the registration date year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
220	     * from the owner's own fields; {@code null} until both the customer code and registration date
221	     * are set.
222	     */
223	    @Transient
224	    public String getMembershipNumber() {
225	        if (this.customerCode == null || this.registrationDate == null) {
226	            return null;
227	        }
228	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
229	    }
230	
231	    /**
232	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
233	     * {@code customerCode}. Derived from the owner's own fields; {@code null} until the customer
234	     * code is set. The standard Luhn algorithm is applied to the digits of the customer code, from
235	     * right to left, doubling every second digit (subtracting 9 when the doubled value exceeds 9).
236	     */
237	    @Transient
238	    public Integer getCheckDigit() {
239	        if (this.customerCode == null) {
240	            return null;
241	        }
242	        int sum = 0;
243	        boolean dbl = true;
244	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
245	            char c = this.customerCode.charAt(i);
246	            if (c < '0' || c > '9') {
247	                continue;
248	            }
249	            int d = c - '0';
250	            if (dbl) {
251	                d *= 2;
252	                if (d > 9) {
253	                    d -= 9;
254	                }
255	            }
256	            sum += d;
257	            dbl = !dbl;
258	        }
259	        return (10 - (sum % 10)) % 10;
260	    }
261	
262	    /**
263	     * The owner's numeric membership level, from 1 to 3. It starts at 1, gains 1 when the owner has
264	     * an email address, gains 1 when the owner is unique (namesakeCount is 0), and is capped at 3
265	     * (level 4 is reserved for tenure). The inputs are the owner's own fields.
266	     */
267	    @Transient
268	    public Integer getMembershipLevel() {
269	        int level = 1;
270	        boolean hasEmail = this.email != null && !this.email.isBlank();
271	        if (hasEmail) {
272	            level++;
273	        }
274	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
275	        if (unique) {
276	            level++;
277	        }
278	        return Math.min(level, 3);
279	    }
280	
281	    /**
282	     * The owner's locality: the canonical region carried by the {@code customerCode}, which is the
283	     * {@code <REGION>} segment preceding its first {@code '-'} (e.g. {@code 'NSW'} for customer code
284	     * {@code 'NSW-1A2B3C4D'}). The region is the one derived from the postcode at creation time and
285	     * baked into the identity. {@code 'UNKNOWN'} when the owner has no customer code yet.
286	     */
287	    @Transient
288	    public String getLocality() {
289	        if (this.customerCode == null) {
290	            return "UNKNOWN";
291	        }
292	        int dash = this.customerCode.indexOf('-');
293	        return dash < 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
294	    }
295	
296	    /**
297	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
298	     * formatted {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. The
299	     * telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
300	     * owner has none), and the household id the stored shared identifier (empty when the owner is
301	     * not part of a shared household). Two owners are duplicates only when their whole identity keys
302	     * are equal; because the telephone is part of the key, two members of the same household with
303	     * different telephones have different identity keys.
304	     */
305	    @Transient
306	    public String getIdentityKey() {
307	        String telephonePart = this.telephone == null ? "" : this.telephone;
308	        String emailPart = this.email == null ? "" : this.email;
309	        String householdPart = this.householdId == null ? "" : this.householdId;
310	        return telephonePart + "|" + emailPart + "|" + householdPart;
311	    }
312	
313	    /**
314	     * The owner's preferred contact channel, derived from the owner's own fields:
315	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
316	     */
317	    @Transient
318	    public String getContactPreference() {
319	        boolean hasEmail = this.email != null && !this.email.isBlank();
320	        return hasEmail ? "EMAIL" : "PHONE";
321	    }
322	
323	    /**
324	     * The owner's age band, derived from the owner's own fields: the whole number of years from
325	     * {@code birthDate} to {@code registrationDate} placed into a band — {@code 'MINOR'} when under
326	     * 18, {@code 'ADULT'} when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is measured
327	     * as of the registration date rather than today, so the band is stable over time. {@code null}
328	     * when the owner has no birth date (or no registration date to measure against).
329	     */
330	    @Transient
331	    public String getAgeBand() {
332	        if (this.birthDate == null || this.registrationDate == null) {
333	            return null;
334	        }
335	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
336	        if (age < 18) {
337	            return "MINOR";
338	        }
339	        if (age < 65) {
340	            return "ADULT";
341	        }
342	        return "SENIOR";
343	    }
344	
345	    protected Set<Pet> getPetsInternal() {
346	        if (this.pets == null) {
347	            this.pets = new HashSet<>();
348	        }
349	        return this.pets;
350	    }
351	
352	    protected void setPetsInternal(Set<Pet> pets) {
353	        this.pets = pets;
354	    }
355	
356	    public List<Pet> getPets() {
357	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
358	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
359	        return Collections.unmodifiableList(sortedPets);
360	    }
361	
362	    public void setPets(List<Pet> pets) {
363	        this.pets = new HashSet<>(pets);
364	    }
365	
366	    public void addPet(Pet pet) {
367	        getPetsInternal().add(pet);
368	        pet.setOwner(this);
369	    }
370	
371	    /**
372	     * Return the Pet with the given name, or null if none found for this Owner.
373	     *
374	     * @param name to test
375	     * @return true if pet name is already in use
376	     */
377	    public Pet getPet(String name) {
378	        return getPet(name, false);
379	    }
380	
381	    /**
382	     * Return the Pet with the given name, or null if none found for this Owner.
383	     *
384	     * @param name to test
385	     * @return true if pet name is already in use
386	     */
387	    public Pet getPet(String name, boolean ignoreNew) {
388	        name = name.toLowerCase();
389	        for (Pet pet : getPetsInternal()) {
390	            if (!ignoreNew || !pet.isNew()) {
391	                String compName = pet.getName();
392	                compName = compName.toLowerCase();
393	                if (compName.equals(name)) {
394	                    return pet;
395	                }
396	            }
397	        }
398	        return null;
399	    }
400	
401	    public Pet getPet(Integer petId) {
402	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
403	    }
404	
405	    @Override
406	    public String toString() {
407	        return new ToStringCreator(this)
408	
409	            .append("id", this.getId())
410	            .append("new", this.isNew())
411	            .append("lastName", this.getLastName())
412	            .append("firstName", this.getFirstName())
413	            .append("address", this.address)
414	            .append("city", this.city)
415	            .append("telephone", this.telephone)
416	            .toString();
417	    }
418	}
